function ExecImage(props) {
	const nameTxt = String(props.name).replace('_',' ')
	return(
	<div className="image-and-text">
		<img
			src={props.image}
			alt={props.nametxt}
			style={{
				width: "80%",
				height: "80%",
				minWidth: 300,
				minHeight: 300
			}}
		/>
		<p style={{ margin: "20px 0 0 0", fontSize: "4vmin", fontWeight: 600, textAlign: "center"}}>{props.nametxt}</p>
		<p style={{ margin: 0 }}>{props.year}</p>
	</div>
	);
}
export default ExecImage;
